<?php
namespace App\Domain\AI\Runtime\Services;
use App\Domain\AI\Agents\Enums\AgentVersionStatus;use App\Domain\AI\Agents\Models\{Agent,AgentVersion};use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Contracts\KnowledgeRetriever;use App\Domain\AI\Knowledge\Data\{KnowledgeSearchMatch,KnowledgeSearchQuery};use App\Domain\AI\Providers\ProviderRegistry;use App\Domain\AI\Runtime\Data\{AgentRuntimeResponseData,ModelRequestData,RuntimeQuestionData};use App\Domain\AI\Runtime\Enums\RuntimeRunStatus;use App\Domain\AI\Runtime\Exceptions\{InvalidModelResponseException,ModelProviderAuthenticationException,ModelProviderNotConfiguredException,ModelProviderRateLimitException,ModelProviderTimeoutException,ModelProviderUnavailableException};use App\Domain\AI\Runtime\Models\RuntimeRun;use App\Domain\AI\Runtime\Policy\AgentRuntimePolicyCompiler;use App\Domain\AI\Runtime\Support\RuntimeOutputSchema;use App\Domain\AI\Tenancy\AiTenantBoundary;use App\Models\User;use Illuminate\Support\Facades\DB;
final class GenerateAgentDraftResponseService
{
 public function __construct(private AiLifecycleAuthorization$auth,private AiTenantBoundary$tenants,private KnowledgeRetriever$retriever,private ProviderRegistry$providers,private AgentRuntimePolicyCompiler$policy){}
 public function generate(User$actor,Agent$agent,RuntimeQuestionData$q):AgentRuntimeResponseData{$authorized=$this->auth->authorize($actor);$this->tenants->assertResourceBelongsToCurrentTenant($agent);[$agent,$version]=DB::transaction(function()use($agent){$a=Agent::query()->lockForUpdate()->with('contract')->findOrFail($agent->id);$v=AgentVersion::query()->where('agent_id',$a->id)->whereIn('status',[AgentVersionStatus::Draft->value,AgentVersionStatus::Testing->value])->orderByDesc('version_number')->lockForUpdate()->firstOrFail();if(!$a->contract||!$v->agent_contract_version_id)throw new \DomainException('A complete draft aggregate is required.');$v->load('contractVersion');if(!$v->contractVersion||$v->contractVersion->agent_contract_id!==$a->contract->id)throw new \DomainException('The runtime aggregate is inconsistent.');return[$a,$v];});$matches=$this->limit($this->retriever->retrieve($version,KnowledgeSearchQuery::from($q->value,6)));$run=$this->start($authorized,$agent,$version);if($matches===[]){DB::transaction(fn()=>$run->fresh()->skip($this->auth->authorize($actor)));return new AgentRuntimeResponseData('No encontramos información suficiente para responder.',[],'low',true,'insufficient_knowledge',[]);}$ids=[];$knowledge=[];foreach($matches as$i=>$m){$id='K'.($i+1);$ids[]=$id;$knowledge[]=['citation_id'=>$id,'source_name'=>$m->sourceName,'version'=>$m->versionNumber,'locator'=>$m->locator,'excerpt'=>$m->excerpt];}$request=new ModelRequestData($this->policy->compile($agent,$version),['question'=>$q->value,'knowledge'=>$knowledge],RuntimeOutputSchema::schema(),600,'none',$this->safety($authorized->tenantId,$authorized->actorUserId),'agent_draft_simulation');try{$model=$this->providers->model()->generate($request);$valid=AgentRuntimeResponseData::validate($model->structuredOutput,$ids);$sources=[];foreach($valid->citationIds as$id)$sources[]=$knowledge[((int)substr($id,1))-1];$result=new AgentRuntimeResponseData($valid->answer,$valid->citationIds,$valid->confidence,$valid->needsHandoff,$valid->handoffReason,$sources);$pricing=(config('ai.providers.openai.pricing')??[])[$model->model]??null;if(!is_array($pricing))throw new InvalidModelResponseException('Pricing snapshot is not configured.');DB::transaction(fn()=>$run->fresh()->complete($this->auth->authorize($actor),$model,$result,$pricing));return$result;}catch(\Throwable$e){$code=match(true){$e instanceof ModelProviderNotConfiguredException=>'provider_not_configured',$e instanceof ModelProviderAuthenticationException=>'provider_authentication',$e instanceof ModelProviderRateLimitException=>'provider_rate_limit',$e instanceof ModelProviderTimeoutException=>'provider_timeout',$e instanceof ModelProviderUnavailableException=>'provider_unavailable',$e instanceof InvalidModelResponseException=>'invalid_model_response',default=>'runtime_failed'};DB::transaction(fn()=>$run->fresh()->fail($this->auth->authorize($actor),$code));throw$e;}}
 private function start($actor,Agent$a,AgentVersion$v):RuntimeRun{return DB::transaction(function()use($actor,$a,$v){$r=new RuntimeRun();$r->agent_id=$a->id;$r->agent_version_id=$v->id;$r->purpose='agent_draft_simulation';$r->status=RuntimeRunStatus::Started;$r->input_units=$r->cached_input_units=$r->output_units=$r->total_units=$r->estimated_cost_microusd=0;$r->input_price_microusd_per_million=$r->cached_input_price_microusd_per_million=$r->output_price_microusd_per_million=0;$r->citation_count=0;$r->needs_handoff=false;$r->created_by_user_id=$actor->actorUserId;$r->started_at=now();$r->save();return$r;});}private function limit(array$matches):array{$out=[];$chars=0;foreach(array_slice($matches,0,6)as$m){$remaining=12000-$chars;if($remaining<=0)break;$excerpt=mb_substr($m->excerpt,0,min(1200,$remaining));if($excerpt==='')continue;$out[]=new KnowledgeSearchMatch($m->sourceUuid,$m->sourceName,$m->versionNumber,$m->sourceType,$m->locator,$excerpt,$m->score,$m->sequence);$chars+=mb_strlen($excerpt);}return$out;}private function safety(int$tenant,int$user):string{$key=(string)config('app.key');if($key==='')throw new ModelProviderNotConfiguredException('Application safety material is not configured.');return hash_hmac('sha256',$tenant.':'.$user.':agent_draft_simulation',$key);}
}
